/* Focused customer compositions. Payment and Pause rules remain owned by their engines. */
(()=>{
'use strict';
const E=L.e,M=L.money,B=L.btn;
const top=(label,back=true,backAction='L.back()')=>`<div class="topline focus-top">${back?B(L.icon('arrowLeft',22),backAction,'icon-btn').replace('<button ','<button aria-label="Go back" '): '<span class="wordmark wordmark-small" aria-label="Lumo"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></span>'}<span class="eyebrow">${E(label)}</span>${B(L.icon('help',21),"L.go('help',{returnTo:L.route,returnParams:L.params})",'icon-btn').replace('<button ','<button aria-label="Get help" ')}</div>`;
const art=(kind,cls='')=>`<div class="focus-art ${cls}">${L.illustration(kind,/review-stage|pause-stage/.test(cls))}</div>`;
// Overview privacy is session-only. Masked markup never contains its numeric value.
let revealed=!L.state.locked,account=L.state;
const overviewNumber=value=>L.balanceNumber(value);
const hiddenMoney=()=>'<span class="money-mask" aria-label="Amount hidden"><span aria-hidden="true">•••••</span></span>';
L.privateMoney=(key,value,large=false,prefix='')=>!['available','room','savings'].includes(key)?prefix+M(value):`<span data-private-value="${key}" data-money-format="${large?'balance':'text'}" ${large?'aria-live="polite" aria-atomic="true"':''}>${revealed?(large?overviewNumber(value):prefix+M(value)):hiddenMoney()}</span>`;
const eye=()=>revealed?L.icon('eye',21):`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path d="m3 3 18 18"/></svg>`;
const eyeContent=(compact=false)=>`${eye()}<span>${revealed?'Hide':'Show'}${compact?'':' balances'}</span>`;
const eyeControl=(compact=false,targets=null)=>`<button type="button" class="balance-eye" id="balance-eye" ${compact?'data-privacy-compact="true" ':''}onclick="L.toggleBalancePrivacy()" aria-label="${revealed?'Hide':'Show'} balances" aria-pressed="${revealed}" aria-controls="${targets||`overview-balance overview-savings${L.hasMeaningfulPlan()?' overview-room':''}`}">${eyeContent(compact)}</button>`;
L.balancePrivacyControl=eyeControl;
L.refreshPrivateMoney=()=>{
 const b=L.balances();
 const values={available:b.available,room:b.room,savings:L.accountBalances?.().savings||0};
 document.querySelectorAll('[data-private-value]').forEach(el=>{const key=el.getAttribute('data-private-value');el.innerHTML=revealed?(el.getAttribute('data-money-format')==='balance'?overviewNumber(values[key]):M(values[key])):hiddenMoney();});
 const control=document.getElementById('balance-eye');if(control){control.innerHTML=eyeContent(control.getAttribute('data-privacy-compact')==='true');control.setAttribute('aria-label',`${revealed?'Hide':'Show'} balances`);control.setAttribute('aria-pressed',String(revealed));}
 document.querySelectorAll('[data-privacy-hint]').forEach(el=>el.textContent=revealed?(L.hasMeaningfulPlan()?'Tap the eye to hide these two amounts.':'Tap the eye to hide your balance.'):(L.hasMeaningfulPlan())?'Tap the eye to reveal these two amounts.':'Tap the eye to reveal your balance.');
};
L.toggleBalancePrivacy=()=>{revealed=!L.state.locked&&!revealed;L.refreshPrivateMoney();L.motionPrivacy?.(revealed);};
L.hidePrivateMoney=()=>{revealed=false;L.refreshPrivateMoney();L.motionPrivacy?.(false);};
L.showPrivateMoney=()=>{revealed=!L.state.locked;L.refreshPrivateMoney();L.motionPrivacy?.(revealed);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)L.hidePrivateMoney();});
window.addEventListener('pagehide',()=>L.hidePrivateMoney());
window.addEventListener('pageshow',event=>{if(event?.persisted)L.hidePrivateMoney();});
const privacyRender=L.render;L.render=()=>{if(account!==L.state){revealed=!L.state.locked;account=L.state;}if(L.state.locked)revealed=false;privacyRender();};
L.openPayTab=tab=>{L.openTab('pay');if(L.payTab()!==tab)L.setPayTab(tab);};
// Home, the detailed story and Chat share the same completed-money-out ledger.
const storyDays=value=>[7,30,90].includes(Number(value))?Number(value):7;
const storyAmount=value=>{const p=L.moneyParts(value);return `${E(p.sign)}<span class="story-currency">${p.currency}</span><span class="story-amount-number">${p.whole}.${p.fraction}</span>`;};
L.homeStorySummary=()=>L.spendingSummary({days:7});
const homeStory=L.homeMoneyStoryCard=()=>{
 const story=L.homeStorySummary(),lead=story.categories[0],tied=lead?story.categories.filter(([,value])=>value===lead[1]):[];
 const single=story.categories.length===1,totalAmount=`<span class="home-story-total">${storyAmount(story.total)}</span>`,leadAmount=lead?(single?totalAmount:storyAmount(lead[1])):'';
 const hasTiedTransfers=tied.some(([name])=>name==='Transfers'),otherTied=tied.find(([name])=>name!=='Transfers');
 const tieNames=hasTiedTransfers&&otherTied?[E(otherTied[0]),'money sent']:tied.slice(0,tied.length===2?2:1).map(([name])=>E(name));
 const others=tied.length-tieNames.length,tieLabel=others?`${tieNames.join(', ')} and ${others} other categor${others===1?'y':'ies'}`:tieNames.join(' and ');
 const observation=lead?.[0]==='Uncategorised'?`${leadAmount} ${single?'paid out':'of '+totalAmount+' paid out'} still needs a category.`:!lead?`No completed payments: ${totalAmount} paid out.`:single?lead[0]==='Transfers'?`All ${totalAmount} paid out was sent in transfers.`:`${E(lead[0])} took all ${totalAmount} paid out.`:tied.length>1?`${tieLabel} accounted for ${leadAmount} each of ${totalAmount} paid out.`:lead[0]==='Transfers'?`You sent ${leadAmount} in transfers, out of ${totalAmount} paid out.`:`${E(lead[0])} took ${leadAmount} of ${totalAmount} paid out.`;
 return `<section class="home-focus-group home-money-story" data-home-focus="story" aria-label="Your money story"><button type="button" class="home-story-open" onclick="L.go('homeMoneyStory',{days:7})"><span class="home-story-heading"><span class="home-story-copy"><span class="home-story-title">Your money story · last 7 days</span><strong class="home-story-insight${lead?'':' home-story-empty'}">${observation}</strong></span><span class="home-story-arrow" aria-hidden="true">${L.icon('chevron',20)}</span></span></button></section>`;
};
L.views.homeMoneyStory=()=>{
 const days=storyDays(L.params.days),story=L.spendingSummary({days}),pending=(L.state.txs||[]).filter(tx=>tx.type==='out'&&tx.status==='pending');
 return `<section class="home-story-detail">${top('Your money story')}<h1>Where did it go?</h1><div class="home-story-periods" role="group" aria-label="Money story period">${[7,30,90].map(d=>B(d+' days',`L.go('homeMoneyStory',{days:${d}})`,'chip'+(d===days?' selected':'')).replace('<button ',`<button aria-pressed="${d===days}" `)).join('')}</div><p class="home-story-scope">Last ${days} days · money out, including fees</p><strong class="home-story-detail-total">${L.balanceNumber(story.total)}</strong>${story.total?`<dl class="home-story-breakdown">${story.categories.map(([name,value])=>`<div><dt>${E(name)}</dt><dd>${storyAmount(value)} <small>${Math.round(value/story.total*100)}%</small></dd></div>`).join('')}</dl>`:'<p class="home-story-no-payments">No completed payments in this period.</p>'}${story.txs.length?`<details class="home-story-transactions"><summary>Recent payments</summary>${story.txs.slice(0,3).map(tx=>`<button type="button" onclick="L.go('txDetail',{id:${E(JSON.stringify(tx.id))}})"><span><strong>${E(tx.name)}</strong><small>${E(tx.category||'Other')}</small></span><span>${storyAmount(Number(tx.amount)+Number(tx.fee||0))}</span></button>`).join('')}</details>`:''}<details class="home-story-definition"><summary>What counts?</summary><p>Completed outgoing payments, including fees and transfers. Transfers are money sent, not purchases. Money received, pending payments and Money Box transfers aren’t included.</p></details>${pending.length?B(pending.length+' payment'+(pending.length===1?'':'s')+' in progress '+L.icon('arrowRight',17),"L.go('pending')",'text-btn'):''}<div class="actions">${story.total?B('View payments',`L.go('activity',{scope:'spending',filter:'out',days:${days}})`,'secondary'):B('View all activity',"L.go('activity')",'secondary')}${B('Ask about this',`L.go('chat',{question:'Where did my money go?',days:${days}})`,'text-btn')}</div></section>`;
};
L.views.home=()=>{
 const s=L.state,b=L.balances(),PM=L.planMoney||M,name=E(s.profile.name.split(' ')[0]);
 const hasPlan=L.hasMeaningfulPlan(s);
 const fundingActions=`<div class="focus-main-actions home-funding-actions">${B(L.icon('plus',20)+' Add money',"L.openFunding('home')")}${B(L.icon('arrowDown',20)+' Request money','L.newRequest()','secondary')}</div>`;
 const pendingStatus=b.held?`<button class="home-pending-status" onclick="L.go('pending')">${L.icon('clock',16)} Payment in progress ${L.icon('chevron',16)}</button>`:'';
 const plan=hasPlan?`<button class="focus-plan home-plan-summary" onclick="L.go('planExplanation')" data-insight data-decision-state="${b.gap?'shortfall':'covered'}" aria-label="Left after your plan. Open explanation"><span><small>Left after your plan</small><strong id="overview-room">${L.privateMoney('room',b.room,true)}</strong><span class="home-plan-math">After <b>${PM(b.essentials)}</b> for essentials and <b>${PM(b.allocated)}</b> for goals.</span><span class="plan-scope-cue" data-plan-scope>${E(L.planScopeSummary(s).label)}</span>${b.gap?`<em>${L.icon('help',15)} ${M(b.gap)} still uncovered</em>`:''}</span>${L.icon('chevron',17)}</button>`:`<button class="home-plan-invite" onclick="L.openPlanBenefit()"><span><strong>${s.planDraft?'Pick up your plan':'What must this money cover?'}</strong><small>${s.planDraft?'Your progress is saved.':'Start with food, transport or data.'}</small></span>${L.icon('arrowRight',20)}</button>`;
 return `<section class="focus-home" data-illustrated-screen="home"><h1 class="sr-only">Home</h1><div class="home-greeting"><span class="wordmark" aria-label="Lumo"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></span><div class="inline">${B(L.icon('bell',22),"L.go('notifications')",'icon-btn').replace('<button ','<button aria-label="Updates" ')}${B(name[0],"L.go('profile')",'avatar').replace('<button ','<button aria-label="Your profile" ')}</div></div><div class="home-intro"><p>Hey, ${name}.</p></div>${art('home','home-stage home-hero-stage')}<div class="home-focus-group" data-home-focus="money" role="group" aria-label="Your money"><div class="home-overview"><div class="focus-money${hasPlan?' has-saved-plan':''}"><div class="home-account-line"><div class="balance-caption"><span>Available balance</span><div class="focus-amount" id="overview-balance">${L.privateMoney('available',b.available,true)}</div></div>${eyeControl()}</div>${hasPlan?plan:''}</div></div>${hasPlan?'':plan}</div><div class="home-focus-group" data-home-focus="actions" role="group" aria-label="Add or request money">${fundingActions}${pendingStatus}</div>${homeStory()}</section>`;

};
// Preserve the accessible tabs, merchant lookup, draft recovery and all destinations.
const pay=L.views.pay;
L.views.pay=()=>{
 const tab=L.payTab(),copy={send:['Make your move.','To a friend, a wallet or a bank.'],campus:['Your everyday places.','Lunch. Printing. A ride to lectures.'],bills:['Life, topped up.','Keep the everyday things going.']}[tab];
 return pay().replace('<div class="pay-hero">',`<div class="focus-pay-heading"><h1>${copy[0]}</h1><p>${copy[1]}</p></div><div class="pay-hero focus-pay-art">`).replace('<h1 class="sr-only">Pay</h1>','');
};
const review=L.views.paymentReview;
L.views.paymentReview=()=>{
 const d=L.state.paymentDraft,original=review();
 // Keep the engine's closed-bill and already-submitted paths intact.
 if(!d||d.submittedTxId||!original.includes('L.continuePayment()')&&!original.includes("L.openFunding('paymentReview')"))return original;
 const total=Number(d.amount)+Number(d.fee||0),short=Math.max(0,total-L.balances().available),essential=L.state.essentials.find(x=>x.id===d.essentialId);
 const method=d.bill?({airtime:'Airtime',data:'Data bundle',electricity:'Electricity',water:'Water',tv:'TV subscription',internet:'Internet'}[d.bill]||'Bill payment'):({lumo:'Lumo transfer',momo:'Mobile money',bank:'Bank transfer',campus:'Campus Pay',request:'Money request'}[d.method]||'Payment');
 return `<section class="focus-review" data-illustrated-screen="paymentReview">${top('Review payment')}${art('pay','review-stage')}<div class="focus-payment-title"><span class="eyebrow">Amount</span><h1>${L.balanceNumber(d.amount)}</h1><p>to <strong>${E(d.name)}</strong></p><small>${E([...new Set([method,d.provider,d.destination].filter(Boolean))].join(' · '))}</small></div><div class="focus-receipt"><div><span>Fee</span><strong>${M(d.fee)}</strong></div><div class="focus-total"><span>Total to pay</span><strong>${M(total)}</strong></div></div>${d.product||d.note||essential?`<details class="focus-details"><summary>Payment details</summary>${d.product?`<p>${E(d.product)}</p>`:''}${d.note?`<p>${E(d.note)}</p>`:''}${essential?`<p>Budget item: ${E(essential.name)}</p>`:''}</details>`:''}${short?`<div class="warning">${M(short)} more needed. Add money or edit the amount.</div>`:''}<div id="error" role="alert"></div><div class="actions">${short?B('Add money',"L.openFunding('paymentReview')"):B('Continue '+L.icon('arrowRight',19),'L.continuePayment()')}${B(d.requestId?'Back to request':'Edit payment',d.requestId?`L.go('requestDetail',{id:'${E(d.requestId)}'})`:'L.editPayment()','secondary')}${B('Cancel payment','L.leavePayment()','text-btn')}</div><p class="focus-footnote">Nothing sent yet. Authorise on the next step.</p></section>`;
};
const pause=L.views.pause;
L.views.pause=()=>{
 const d=L.state.paymentDraft;if(!d||d.submittedTxId)return pause();
 const q=L.pauseEngine.evaluate(d);if(!q.triggered)return L.views.paymentReview();
 L.pauseEngine.present(d);
 const PM=L.planMoney||M,impact=L.planImpactSummary(d),planImpact=q.planImpact;
 const headline=planImpact?impact.headline:q.selected.code==='low_balance'?`${PM(Math.max(0,q.after))} would be left in your account.`:q.selected.message;
 const consequence=planImpact?`<p class="pause-essentials-explanation">${E(impact.essentialsExplanation)}</p>${impact.goalExplanation?`<p class="pause-goal-impact">${E(impact.goalExplanation)}</p>`:''}${impact.essentialGap&&impact.goalGap?`<p class="pause-total-impact">${E(impact.totalExplanation)}</p>`:''}${impact.totalGapBefore?`<p class="pause-existing-gap">Includes ${PM(impact.totalGapBefore)} already uncovered before this payment.</p>`:''}`:`<div class="pause-simple-figures"><span>After this payment</span><strong>${PM(Math.max(0,q.after))}</strong></div>`;
 const editLabel=d.requestId||d.fixedAmount?'Review payment':'Edit amount';
 return `<section class="focus-pause focus-pause-compact" data-illustrated-screen="pause">${top('Pause Moment',true,"L.go('paymentReview')")}<div class="pause-decision-heading">${art('pause','pause-stage')}<div class="focus-pause-insight" data-insight data-decision-state="${planImpact?impact.consequenceTone:'attention'}"><h1>${E(headline)}</h1></div></div><p class="pause-payment-context"><span class="projection-tag">Considering</span> ${PM(Number(d.amount)+Number(d.fee||0))} to ${E(d.name)}${Number(d.fee)>0?' · includes fee':''}</p><div class="pause-decision-consequence" data-projection>${consequence}</div><div id="error" role="alert"></div><div class="actions pause-actions"><div class="pause-decisions">${B(editLabel,"L.pauseAction('edit_amount')",'secondary pause-equal-choice')}${B('Continue','L.resumeFromPause()','secondary pause-equal-choice')}</div>${d.method!=='box'&&L.state.essentials.length?B('This covers a budget item','L.openPaymentPlanLink()','text-btn pause-link-cost'):''}<div class="focus-pause-exits">${B('Decide later',"L.pauseAction('delay_payment')",'text-btn')}${B('Cancel payment',"L.pauseAction('cancel_payment')",'text-btn')}</div></div><p class="focus-footnote">Nothing sent yet. Authorise on the next step.</p></section>`;
};
L.views.story=()=>{
 const days=[7,30,90].includes(Number(L.params.days))?Number(L.params.days):30,category=typeof L.params.category==='string'?L.params.category.slice(0,80):'',cutoff=Date.now()-days*86400000;
 const txs=L.spendingSummary?L.spendingSummary({days,category}).txs:L.state.txs.filter(t=>t.type==='out'&&t.status==='success'&&new Date(t.date).getTime()>=cutoff&&new Date(t.date).getTime()<=Date.now()),groups={};
 txs.forEach(t=>groups[t.category||'Other']=(groups[t.category||'Other']||0)+Number(t.amount)+Number(t.fee||0));
 const categories=Object.entries(groups).sort((a,b)=>b[1]-a[1]),total=categories.reduce((n,[,v])=>n+v,0),lead=categories[0],colours=['#2e3828','#698550','#b5e96a','#d4d9ca','#999f90'];
 const categoryRow=([name,value],i)=>`<button class="focus-category" onclick="L.go('activity',{scope:'spending',filter:'out',days:${days},category:${E(JSON.stringify(name))}})"><div><span><i style="background:${colours[i%colours.length]}"></i>${E(name)}</span><strong>${M(value)} <small>${Math.round(value/total*100)}%</small></strong></div><span class="focus-category-track" aria-hidden="true"><span style="width:${value/total*100}%;background:${colours[i%colours.length]}"></span></span></button>`;
 return `<section class="focus-story" data-illustrated-screen="story">${top('Money story')}<div class="focus-story-heading"><h1>${total?'Now you know<br>where it went.':'Your story<br>starts here.'}</h1><p>${lead?E(lead[0])+' was your biggest category.':'Every completed payment adds a little clarity.'}</p></div>${art('story','story-stage')}${category?`<div class="story-category-scope"><span>${E(category)}</span>${B('All spending',`L.go('story',{days:${days}})`,'text-btn')}</div>`:''}<div class="focus-story-period" role="group" aria-label="Spending period">${[7,30,90].map(d=>B(d+' days',`L.go('story',{days:${d},category:${E(JSON.stringify(category))}})`,'focus-period'+(d===days?' is-active':'')).replace('<button ',`<button aria-pressed="${d===days}" `)).join('')}</div><div class="focus-story-total"><span>SPENT IN ${days} DAYS · INCLUDING FEES</span><strong>${L.balanceNumber(total)}</strong></div>${total?`<div class="focus-categories">${categories.slice(0,3).map(categoryRow).join('')}${categories.length>3?`<details class="focus-details"><summary>${categories.length-3} more categories</summary>${categories.slice(3).map((x,i)=>categoryRow(x,i+3)).join('')}</details>`:''}</div>`:'<p class="focus-empty">Your confirmed spending will appear here.</p>'}<div class="actions">${total?B('Explore my spending '+L.icon('arrowRight',18),`L.go('activity',{scope:'spending',filter:'out',days:${days},category:${E(JSON.stringify(category))}})`):L.balances().available>0?B('Make a payment',"L.openTab('pay')"):B('Add money',"L.openFunding('story')")}${B('Talk it through '+L.icon('chat',17),`L.go('chat',{question:'Where did my money go?',days:${days},category:${E(JSON.stringify(category))}})`,'text-btn')}</div></section>`;
};
// Shared editorial rhythm across the other primary destinations.
L.views.plan=()=>{
 const s=L.state,b=L.balances(),hasPlan=L.hasMeaningfulPlan(s);
 const date=s.allowance.date?new Date(s.allowance.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'';
 const start=s.planDraft?s.planDraft.step||'firstEssentials':'planSetup';
 return `<section class="focus-plan-page simple-plan-page" data-illustrated-screen="plan">${top('My plan',false)}<div class="destination-heading"><h1>${hasPlan?'Your plan.':'What must this money cover?'}</h1><p>${hasPlan?'Your costs first. The rest is yours to plan.':'Start with one cost. See what remains.'}</p></div>${art('goals','destination-stage')}${hasPlan?`<div class="plan-room"><span>Left after your plan</span><strong>${L.balanceNumber(b.room)}</strong><p class="plan-scope-cue" data-plan-scope>${E(L.planScopeSummary(s).label)}</p>${b.gap?B(M(b.gap)+' still uncovered '+L.icon('arrowRight',17),"L.go('makeRoom')",'text-btn'):`<p>${M(b.essentials)} essentials · ${M(b.allocated)} goals</p>`}<div class="plan-period-line">${B(E(L.planPeriodActionLabel?.()||'How long should this money last? Add a date.'),"L.go('planPeriod')",'text-btn')}</div></div>`:''}${!hasPlan||s.planDraft?B(s.planDraft?'Continue my plan':'Build my first plan',`L.go('${E(start)}')`):''}<div class="destination-list">${L.row('Essentials',s.essentials.length?s.essentials.length+' costs · '+M(b.essentials)+' left to cover':'Food, transport, data','plan',s.essentials.length?"L.go('essentials')":s.planDraft?`L.go('${E(start)}')`:"L.go('planSetup')")}${L.row('My goals',s.goals[0]?.name||'Optional · something you’re saving for','target',"L.go('goals')")}${L.row('Expected money',s.allowance.amount?M(s.allowance.amount)+(date?' expected '+date:''):'Optional · an allowance or other income','arrowDown',"L.go('allowance')")}</div><div class="destination-footer">${B('Add a goal',"L.go('goalEdit')",'text-btn')}${B('Your money story '+L.icon('arrowRight',17),"L.go('story')",'text-btn')}${B('Milestones',"L.go('missions')",'text-btn')}</div></section>`;
};
L.views.more=()=>{
 const p=L.state.profile;
 return `<section class="focus-you" data-illustrated-screen="more">${top('You',false)}<div class="destination-heading"><h1>Your Lumo.<br>Your way.</h1><p>${E(p.displayName||p.name)}</p></div>${art('identity','destination-stage')}<div class="you-campus">${L.icon('user',16)} ${E(p.campus||'Your account')}</div><div class="you-options">${[['Profile','Your details','user','profile'],['Account','Details & statements','bank','accountInfo'],['Security','PIN & devices','shield','security'],['Privacy','Your data & choices','eye','privacy'],['Notifications','Your reminders','bell','notificationPrefs'],['Help','We’re here to help','help','help']].map(([name,sub,icon,route])=>`<button onclick="L.go('${route}')"><span>${L.icon(icon,23)}</span><strong>${name}</strong><small>${sub}</small></button>`).join('')}</div>${L.testMode?`<details class="testing-drawer"><summary>Ambassador tools</summary>${L.row('Test guide','Scenarios and sample account','target',"L.go('testing')")}${L.row('Merchant preview','Explore collections','grid',"L.go('merchant')")}${L.row('Feedback','Share what you notice','chat',"L.go('feedback')")}</details>`:''}<div class="destination-footer"><span>Lumo · A little clearer.</span>${B('Sign out','L.acct.signout()','text-btn')}</div></section>`;
};
// Preserve the selected Pay tab's scroll position when its content changes.
L.setPayTab=tab=>{
 if(!['send','campus','bills'].includes(tab))return;
 const view=document.getElementById('view'),scroll=view?.scrollTop||0;
 L.params={...L.params,tab};L.render();if(view)view.scrollTop=scroll;
 document.getElementById('pay-tab-'+tab)?.focus?.({preventScroll:true});
};
})();
